property.value:
//LambdaExpression[
  let $params := (VariableId | LambdaParameterList/LambdaParameter/VariableId),
      $p := $params[1]/@Name
  return count($params) = 1
    and (
      MethodCall[count(ArgumentList/*) = 0][VariableAccess[@Name = $p]]
      or
      MethodCall[ArgumentList[count(*) = 1][VariableAccess[@Name = $p]]]
        [not(VariableAccess[@Name = $p])]
    )
]
